struct cmp {
    bool operator()(const pair<int, int>& a, const pair<int, int>& b) const {
        return a.first < b.first;
    }
};
​
// 解析字符串函数 将[[0,1,0],[0,2,1],[0,0,1]] 转化为二维数字数组
vector<vector<int>> parseInputStr(string input) {
    vector<vector<int>> result;
    if (input.empty()) {
        return result;
    }
    //  [[0,1,0],[0,2,1],[0,0,1]] => 0,1,0],[0,2,1],[0,0,1
    input = input.substr(2, input.size() - 4);
    vector<string> gridRow = split(input, "],[");
    for (int i = 0; i < gridRow.size(); i++) {
        vector<string> tmpStr = split(gridRow[i], ",");
        vector<int> tmp;
        for (int j = 0 ; j < tmpStr.size();j++) {
            tmp.push_back(stoi(tmpStr[j]));
        }
        result.push_back(tmp);
    }
    return result; 
}
