// 最短路算法
int BFS(vector<vector<int>>& grid, vector<vector<int>>& lights) {
    // 四个方向
    vector<vector<int>> directed = {{0,1}, {0, -1}, {1, 0}, {-1, 0}};
    int m = grid.size();
    int n = grid[0].size();
    // 起点/终点就是障碍物
    if (grid[0][0] == 1 || grid[m-1][n-1] == 1) {
        return -1;
    }
​
​
    // 使用哈希存储每个红绿灯的等待时间,便于后续查找
    map<int, int> lightsColWaitMap;
    for (int i = 0; i < lights.size(); i++) {
        int x = lights[i][0];
        int y = lights[i][1];
        int time = lights[i][2];
        int pos = x * n + y;
        lightsColWaitMap[pos] = time;
    }
    // 防止重复访问
    vector<int> visited(m*n ,INT_MAX);
    // 使用优先队列模拟bfs {所用时间,位置}
    priority_queue<pair<int, int>, vector<pair<int,int>>, cmp> pq;
    pq.push({0, 0});
    visited[0] = 0;

    while (!pq.empty()) {
        pair<int,int> top = pq.top();
        pq.pop();
        int pos = top.second;
        int time = top.first;
        int x = pos/ n;
        int y = pos % n;
        // 一秒走一格
        int nextStepTime = time + 1;
        // 额外判断是否为红绿灯
        if (grid[x][y] == 2) {
            nextStepTime += lightsColWaitMap[pos];
        }
        // 向四个方向遍历
        for (int i = 0; i < 4; i++) {
            int nextX = x + directed[i][0];
            int nextY = y + directed[i][1];
            int nextPos = nextX * n + nextY;
            // 越界或者先前有更小步数到达或者为障碍物
            if (nextX < 0 || nextX >= m || nextY < 0 || nextY >= n || visited[nextPos] <= nextStepTime || grid[nextX][nextY] == 1) {
                continue;
            }

            visited[nextPos] = nextStepTime;
            pq.push({nextStepTime, nextPos});
        }
    }
​
    return visited[m * n - 1] == INT_MAX ? -1 : visited[m * n - 1];
}
