int main() {
    string gridStr;
    getline(cin, gridStr);
    string lightsStr;
    getline(cin, lightsStr);

    vector<vector<int>> grid = parseInputStr(gridStr);
    vector<vector<int>> lights = parseInputStr(lightsStr);
    int res = BFS(grid, lights);
    cout << res;
    return 0;
}

