import java.util.*;
​
public class Main {
​
    // 解析字符串函数
    static List<List<Integer>> parseInput(String input) {
        List<List<Integer>> result = new ArrayList<>();
        input = input.trim();
        if (input.length() <= 4) return result; // 包括 [[ 和 ]]
        input = input.substring(2, input.length() - 2); // 去除外层 [[ 和 ]]
        String[] rows = input.split("],\\["); // 正确：用双反斜杠
        for (String row : rows) {
            List<Integer> nums = new ArrayList<>();
            for (String num : row.split(",")) {
                nums.add(Integer.parseInt(num));
            }
            result.add(nums);
        }
        return result;
    }
​
    // 最短路算法
    static int bfs(List<List<Integer>> grid, List<List<Integer>> lights) {
        int m = grid.size();
        int n = grid.get(0).size();
        int[][] directions = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
​
        // 起点或终点为障碍物
        if (grid.get(0).get(0) == 1 || grid.get(m - 1).get(n - 1) == 1) {
            return -1;
        }
​
        // 使用 HashMap 存储红绿灯等待时间
        Map<Integer, Integer> lightMap = new HashMap<>();
        for (List<Integer> light : lights) {
            int x = light.get(0), y = light.get(1), t = light.get(2);
            int pos = x * n + y;
            lightMap.put(pos, t);
        }
​
        int[] visited = new int[m * n];
        Arrays.fill(visited, Integer.MAX_VALUE);
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0])); // (time, pos)
​
        pq.offer(new int[]{0, 0});
        visited[0] = 0;
​
        while (!pq.isEmpty()) {
            int[] top = pq.poll();
            int time = top[0], pos = top[1];
            int x = pos / n, y = pos % n;
​
            int nextTime = time + 1; // 每次移动耗时 1
​
            // 当前是红绿灯
            if (grid.get(x).get(y) == 2) {
                nextTime += lightMap.getOrDefault(pos, 0);
            }
​
            for (int[] dir : directions) {
                int nx = x + dir[0];
                int ny = y + dir[1];
                int npos = nx * n + ny;
​
                // 越界、障碍或已有更优解
                if (nx < 0 || nx >= m || ny < 0 || ny >= n) continue;
                if (grid.get(nx).get(ny) == 1 || visited[npos] <= nextTime) continue;
​
                visited[npos] = nextTime;
                pq.offer(new int[]{nextTime, npos});
            }
        }
​
        return visited[m * n - 1] == Integer.MAX_VALUE ? -1 : visited[m * n - 1];
    }
​
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String gridStr = sc.nextLine();
        String lightsStr = sc.nextLine();
​
        List<List<Integer>> grid = parseInput(gridStr);
        List<List<Integer>> lights = parseInput(lightsStr);
​
        System.out.println(bfs(grid, lights));
    }
}
