import (
    "bufio"
    "container/heap"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
// 解析输入格式 "[[0,1,0],[0,2,1],[0,0,1]]"
func parseInput(s string) [][]int {
    s = strings.TrimSpace(s)
    if len(s) <= 4 {
        return [][]int{}
    }
    s = s[2 : len(s)-2]
    rows := strings.Split(s, "],[")
    result := [][]int{}
    for _, row := range rows {
        nums := strings.Split(row, ",")
        temp := []int{}
        for _, num := range nums {
            n, _ := strconv.Atoi(num)
            temp = append(temp, n)
        }
        result = append(result, temp)
    }
    return result
}
​
// 自定义最小堆，元素为 (time, position)
type Item struct {
    time int
    pos  int
}
type PriorityQueue []Item
​
func (pq PriorityQueue) Len() int           { return len(pq) }
func (pq PriorityQueue) Less(i, j int) bool { return pq[i].time < pq[j].time }
func (pq PriorityQueue) Swap(i, j int)      { pq[i], pq[j] = pq[j], pq[i] }
​
func (pq *PriorityQueue) Push(x any) {
    *pq = append(*pq, x.(Item))
}
func (pq *PriorityQueue) Pop() any {
    old := *pq
    n := len(old)
    item := old[n-1]
    *pq = old[:n-1]
    return item
}
​
// 最短路算法
func bfs(grid, lights [][]int) int {
    m, n := len(grid), len(grid[0])
    if grid[0][0] == 1 || grid[m-1][n-1] == 1 {
        return -1
    }
    directions := [][]int{{0, 1}, {0, -1}, {1, 0}, {-1, 0}}
​
    // 哈希表存储红绿灯时间
    lightMap := map[int]int{}
    for _, light := range lights {
        x, y, t := light[0], light[1], light[2]
        pos := x*n + y
        lightMap[pos] = t
    }
​
    visited := make([]int, m*n)
    for i := range visited {
        visited[i] = 1<<31 - 1
    }
    pq := &PriorityQueue{}
    heap.Init(pq)
    heap.Push(pq, Item{0, 0})
    visited[0] = 0
​
    for pq.Len() > 0 {
        item := heap.Pop(pq).(Item)
        t, pos := item.time, item.pos
        x, y := pos/n, pos%n
        nextTime := t + 1
​
        // 红绿灯等待时间
        if grid[x][y] == 2 {
            nextTime += lightMap[pos]
        }
​
        for _, d := range directions {
            nx, ny := x+d[0], y+d[1]
            npos := nx*n + ny
            // 越界 障碍物 之前到达过并且距离更小
            if nx < 0 || nx >= m || ny < 0 || ny >= n || grid[nx][ny] == 1 || visited[npos] <= nextTime {
                continue
            }
            visited[npos] = nextTime
            heap.Push(pq, Item{nextTime, npos})
        }
    }
​
    res := visited[m*n-1]
    if res == 1<<31-1 {
        return -1
    }
    return res
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    gridStr, _ := reader.ReadString('\n')
    lightStr, _ := reader.ReadString('\n')
    grid := parseInput(gridStr)
    lights := parseInput(lightStr)
    fmt.Println(bfs(grid, lights))
}
